<html lang="es">
<head><meta charset="utf-8"><title>PROBE TOUCH</title></head>
<body>
<pre id="out">PROBE_START</pre>
<script>
const log = [];
function say(s){ log.push(s); document.getElementById('out').textContent = log.join('\n'); }
window.addEventListener('error', function(e){ say('JS_ERROR: ' + e.message + ' @' + e.lineno); });

setTimeout(function(){
  try{
    say('viewport innerWidth=' + innerWidth + 'x' + innerHeight);
    say('isTouch=' + (typeof isTouch !== 'undefined' ? isTouch : 'undef'));
    say('lockout presente=' + !!document.getElementById('secLockout'));

    say('openNaves type=' + typeof openNaves);
    openNaves();
    say('navesGame .show=' + document.getElementById('navesGame').classList.contains('show'));
    say('joy .show tras abrir=' + document.getElementById('touchJoy').classList.contains('show'));

    window.nvStart();
    say('NV.state tras nvStart=' + NV.state);
  }catch(err){ say('PROBE_ERR(1): ' + err.message); }
}, 2500);

setTimeout(function(){
  try{
    say('joy .show jugando=' + document.getElementById('touchJoy').classList.contains('show'));
    say('btns .show jugando=' + document.getElementById('touchBtns').classList.contains('show'));
    const btns = document.querySelectorAll('.tbtn');
    say('tbtn count=' + btns.length);
    const cs = getComputedStyle(document.getElementById('touchBtns'));
    say('touchBtns display=' + cs.display + ' zIndex=' + cs.zIndex);
    const csj = getComputedStyle(document.getElementById('touchJoy'));
    say('touchJoy display=' + csj.display);
    const r = document.getElementById('touchBtns').getBoundingClientRect();
    say('touchBtns rect=' + Math.round(r.left) + ',' + Math.round(r.top) + ' ' + Math.round(r.width) + 'x' + Math.round(r.height));
    const rj = document.getElementById('touchJoy').getBoundingClientRect();
    say('touchJoy rect=' + Math.round(rj.left) + ',' + Math.round(rj.top) + ' ' + Math.round(rj.width) + 'x' + Math.round(rj.height));
    say('NV.state=' + NV.state + ' round=' + NV.round + ' HUD show=' + document.getElementById('nvHUD').classList.contains('show'));
    say('lockout presente=' + !!document.getElementById('secLockout'));
    say('canvas=' + document.getElementById('nvCanvas').width + 'x' + document.getElementById('nvCanvas').height);
    // accion real de un boton tactil
    NV.round = 3; NV.bombs = 2;
    document.querySelector('.tbtn.bmb').dispatchEvent(new Event('touchstart', {bubbles:true}));
    say('tras tap BOMB -> NV.bombT=' + NV.bombT);
    say('PROBE_END');
  }catch(err){ say('PROBE_ERR(2): ' + err.message); }
}, 6000);
</script>
</body>
</html>
"}

