{"content": "// Servidor estático mínimo solo para verificación local (no forma parte del proyecto).
const http = require('http');
const fs = require('fs');
const path = require('path');
const root = process.argv[2] || process.cwd();
const port = Number(process.argv[3] || 8099);
const types = { '.html':'text/html; charset=utf-8', '.js':'text/javascript; charset=utf-8',
  '.css':'text/css; charset=utf-8', '.json':'application/json; charset=utf-8',
  '.svg':'image/svg+xml', '.png':'image/png', '.jpg':'image/jpeg', '.jpeg':'image/jpeg', '.txt':'text/plain' };
http.createServer(function(req, res){
  const urlPath = decodeURIComponent(req.url.split('?')[0]);
  let file = path.join(root, urlPath === '/' ? '/index.html' : urlPath);
  if (!file.startsWith(root)) { res.writeHead(403); return res.end('forbidden'); }
  fs.readFile(file, function(err, buf){
    if (err) { res.writeHead(404, {'Content-Type':'text/plain'}); return res.end('not found: ' + urlPath); }
    res.writeHead(200, { 'Content-Type': types[path.extname(file).toLowerCase()] || 'application/octet-stream' });
    res.end(buf);
  });
}).listen(port, '127.0.0.1', function(){ console.log('static server on http://127.0.0.1:' + port); });
