:root {
  --arc-cyan:#00d4ff; --arc-green:#00ff41; --arc-red:#ff003c; --arc-amber:#fbbf24;
  --panel:#252535; --panel-border:#3d3d4d; --text-dim:#94a3b8; --text-bright:#e2e8f0;
  /* Alto real de la taskbar y alto visible del viewport.
