{"file_path": "C:\Users\BFFF\Documents\proyecto\css\console.css", "new_string": "  /* Extra small phones */
  @media (max-width:390px) {
    .dicons { grid-template-columns:repeat(auto-fill,minmax(76px,1fr)); gap:12px 8px; }
    .meme-grid { grid-template-columns:1fr !important; }
    .home-tiles { grid-template-columns:repeat(2,1fr); }
    .lb-table { font-size:13px; }
    .lb-table td:nth-child(3), .lb-table th:nth-child(3) { display:none; }
  }

  /* Móvil en horizontal: hay poca altura, así que el dock y los iconos se compactan
     para que las apps sigan accesibles sin comer pantalla al juego. */
  @media (max-width:950px) and (orientation:landscape) {
    :root { --taskbar-h:calc(40px + env(safe-area-inset-bottom, 0px)); }
    .mobile-dock { flex-direction:row; top:auto; bottom:calc(var(--taskbar-h) + 8px); right:8px;
      max-height:none; max-width:calc(100vw - 100px); overflow-x:auto; overflow-y:hidden; }
    .mobile-dock-btn { width:42px; height:42px; font-size:20px; }
