      padding:10px 62px 10px 10px; }
    .dicon { padding:6px 3px 5px; }
    .dicon .ico { font-size:30px; }
    .window { border-radius:12px 12px 0 0 !important; }
    .home-page { padding:18px 14px; }
    .home-logo { font-size:38px; margin-bottom:10px; }
  }", "old_string": "  /* Extra small phones */
