  const entry = table[ip] || { last: 0, count: 0, day: nowMs, nonces: [] };
  if ((nowMs - entry.last) < MIN_POST_GAP_MS) {
    return { error: 'Rate limited: too many submissions, wait a few seconds', table: table };
  }
  if (entry.count >= MAX_POSTS_PER_DAY) {
