  }
  if (entry.nonces.indexOf(nonce) >= 0) {
    return { error: 'Replay detected: nonce already used', table: table };
  }
  entry.last = nowMs;
  entry.count = (entry.count || 0) + 1;
  entry.nonces = (entry.nonces || []).concat([nonce]).slice(-64);
  table[ip] = entry;
  return { error: null, table: table };
}

