function checkWeeklyEpoch(epochRaw, nowMs) {
  const epoch = Number(epochRaw) || 0;
  if (!epoch || (nowMs - epoch) >= WEEK_MS) return { epoch: nowMs, reset: true };
  return { epoch: epoch, reset: false };
}

