  ABS_SCORE_CAP, PER_ROUND_BUDGET, ROUND_GRACE, MAX_BODY,
  computeSig, cleanWallet, cleanName, deduplicateAndRank, updateOrInsert,
  validateEntry, clientIp, checkRateLimit, checkWeeklyEpoch
};
