    console.log('=== 9. Dedupe por piloto (conserva el mejor) ===');
    await new Promise(function (r) { setTimeout(r, 8100); }); // respeta el gap anti-spam de 8 s
    const mejor = entryFor('NOVA', 9999, 5, '0xvitalik.eth'.replace('0xvitalik.eth', 'vitalik.eth'));
    const r5 = await req('POST', { entry: mejor });
    check('responde 200', r5.status === 200, r5);
    check('un solo registro de NOVA', r5.json.allTime.filter(function (e) { return e.name === 'NOVA'; }).length === 1, r5.json.allTime);
    check('conserva la puntuación mayor', r5.json.allTime[0].score === 9999, r5.json.allTime[0]);

    console.log('=== 10. Rate limit ===');
    const r6 = await req('POST', { entry: entryFor('VELOZ', 100, 1, 'veloz.eth') });
    check('segundo envío seguido -> 429', r6.status === 429, r6);

    console.log('=== 11. Diagnóstico ?debug=1 ===');
    const g2 = await req('GET');
    check('GET sin debug no expone diagnostics', g2.json.diagnostics === undefined);
  } finally {
    proc.kill();
    try { fs.rmSync(dataDir, { recursive: true, force: true }); } catch (e) {}
  }

  console.log('\n=== RESULTADO: ' + pass + ' OK, ' + fail + ' fallos ===');
  process.exit(fail ? 1 : 0);
})().catch(function (e) { console.log('FATAL ' + e.message); process.exit(1); });
