{"file_path": "C:\Users\BFFF\Documents\proyecto\api\records.php", "new_string": "/** Multiplicación FNV de 32 bits REAL.
 *  OJO: en PHP `$h * 0x01000193` se evalúa como float de 64 bits y el `& 0xFFFFFFFF`
 *  posterior NO recupera los bits bajos ya perdidos por el redondeo, así que a
 *  partir de ~16 caracteres el hash divergía del que calcula el cliente en JS.
 *  Resultado: el servidor rechazaba con 403 casi todos los records (y el cliente
 *  ocultaba el error). Esta versión parte el multiplicador en dos mitades de
 *  16 bits y enmascara en cada paso, que es exactamente lo que hace Math.imul. */
function fnvMul32($h, $prime) {
    $lo = $prime & 0xFFFF;
    $hi = ($prime >> 16) & 0xFFFF;
    $loPart = ($h & 0xFFFF) * $lo;
    $hiPart = ((($h >> 16) & 0xFFFF) * $lo + ($h & 0xFFFF) * $hi) & 0xFFFF;
    return (($hiPart << 16) | ($loPart & 0xFFFF)) & 0xFFFFFFFF;
