function fnvMul32php(h, prime) {
  const lo = prime & 0xFFFF;
  const hi = (prime >>> 16) & 0xFFFF;
  const loPart = (h & 0xFFFF) * lo;
  const hiPart = ((((h >>> 16) & 0xFFFF) * lo + (h & 0xFFFF) * hi) & 0xFFFF);
