function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16);
}
const SALT = 'ARC_VIRUS_v5_SALT_9973';
function entryFor(name) {
  const e = { name: name, score: 100, round: 1, date: '01/15/2026', wallet: 'test.eth' };
  e._ts = Date.now();
  e._n = Math.random().toString(16).slice(2) + Math.random().toString(16).slice(2);
  e._sig = fnv1a(e.name + '|' + e.score + '|' + e.round + '|' + e.date + '|' + e._ts + '|' + e._n + '|' + e.wallet + '|' + SALT);
  return e;
}
function post(body) {
  return new Promise(function (resolve, reject) {
    const payload = JSON.stringify(body);
    const r = http.request({ host: '127.0.0.1', port: PORT, path: '/api/records', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } }, function (res) {
      let d = ''; res.on('data', function (c) { d += c; }); res.on('end', function () { resolve({ status: res.statusCode, json: JSON.parse(d) }); });
    });
    r.on('error', reject); r.write(payload); r.end();
  });
}

(async function () {
  const proc = spawn(process.execPath, [path.join(__dirname, '..', '..', 'api', 'records.node.js'), String(PORT)], {
    env: Object.assign({}, process.env, { ARC_DATA_DIR: dataDir }), stdio: 'ignore'
  });
  await sleep(1200);
  try {
    console.log('POST #1 (VELOZ):', (await post({ entry: entryFor('VELOZ') })).status);
    console.log('  ratelimit.json ->', fs.readFileSync(path.join(dataDir, 'ratelimit.json'), 'utf8'));
    const r2 = await post({ entry: entryFor('RAPIDO') });
    console.log('POST #2 inmediato (RAPIDO):', r2.status, r2.json.error || '');
    console.log('  ratelimit.json ->', fs.readFileSync(path.join(dataDir, 'ratelimit.json'), 'utf8'));
  } finally {
    proc.kill();
    try { fs.rmSync(dataDir, { recursive: true, force: true }); } catch (e) {}
  }
})().catch(function (e) { console.log('FATAL ' + e.message); });
