$entry = node -e "
function fnv1a(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193);}return (h>>>0).toString(16);}
const SALT='ARC_VIRUS_v5_SALT_9973';
const e={name:'ARCADE',score:25000,round:6,date:new Date().toLocaleDateString('en-US'),wallet:'0x1234567890abcdef1234567890abcdef12345678'};
e._ts=Date.now();e._n=Math.random().toString(16).slice(2)+Math.random().toString(16).slice(2);
e._sig=fnv1a(e.name+'|'+e.score+'|'+e.round+'|'+e.date+'|'+e._ts+'|'+e._n+'|'+e.wallet+'|'+SALT);
console.log(JSON.stringify({entry:e}));
"
Write-Host "--- POST valido (con wallet) ---"
$r = Invoke-WebRequest "http://127.0.0.1:8099/api/records" -Method POST -Body $entry -ContentType "application/json" -UseBasicParsing
$j = ConvertFrom-Json $r.Content
"status=$($r.StatusCode) success=$($j.success) registros=$($j.allTime.Count) wallet=$($j.allTime[0].wallet)"
Write-Host "--- GET de vuelta ---"
$g = ConvertFrom-Json (Invoke-WebRequest "http://127.0.0.1:8099/api/records" -UseBasicParsing).Content
