// Escenarios del filtro: se arma la vigilancia SOLO en escritorio real
function allowed(isTouch, maxTouch, mm, param){
  if(param==='off'||param==='0') return false;
  if(param==='on'||param==='1') return true;
  if(isTouch || maxTouch>0) return false;
  if(mm === null) return false;
  try{
    if(!mm('(pointer: fine)').matches) return false;
    if(mm('(hover: none)').matches) return false;
    if(mm('(any-pointer: coarse)').matches) return false;
  }catch(e){ return false; }
  return true;
}
// Simulador de matchMedia
function mk(pointerFine, hoverNone, anyCoarse){
  return function(q){
    if(q==='(pointer: fine)') return {matches:pointerFine};
    if(q==='(hover: none)') return {matches:hoverNone};
    if(q==='(any-pointer: coarse)') return {matches:anyCoarse};
    return {matches:false};
  };
}
const casos = [
  ['iPhone / Android (touch)',        allowed(true, 5, mk(false,true,true), '')],
  ['Tablet con stylus (pointer fine + coarse)', allowed(false, 5, mk(true,false,true), '')],
  ['Android grande con hover (1000px)', allowed(false, 10, mk(true,false,true), '')],
  ['Webview in-app táctil',           allowed(true, 1, mk(true,false,true), '')],
  ['Escritorio real',                 allowed(false, 0, mk(true,false,false), '')],
  ['Escritorio con ?lockdown=off',    allowed(false, 0, mk(true,false,false), 'off')],
  ['Móvil con ?lockdown=on',          allowed(true, 5, mk(false,true,true), 'on')]
];
casos.forEach(function(c){ console.log((c[1]?'SE ARMA  ':'no se arma') + '  ' + c[0]); });
"", "description": "Verify lockdown gate across device scenarios"}

