    const now = Date.now();
    if(now - lastTapHandled < DEDUPE_MS) return;   // dos dedos / doble tap
    lastTapHandled = now;

    // Si el navegador acaba de emitir un click nativo, ese ya hizo el trabajo.
    if(now - clickSeenAt < DEDUPE_MS) return;

    fireSynthetic(target, x, y);

