const fs = require('fs');
const path = require('path');
const src = fs.readFileSync(path.join(__dirname, '..', '..', 'js', 'console.js'), 'utf8');
const start = src.indexOf('function initGlobalTapToClick()');
let depth = 0, end = -1, started = false;
for (let i = start; i < src.length; i++) {
  const c = src[i];
  if (c === '{') { depth++; started = true; }
  else if (c === '}') { depth--; if (started && depth === 0) { end = i + 1; break; } }
}
let fnSrc = src.slice(start, end);

const marks = [
  ['if(!tracking) return;', "if(!tracking){ TRACE.push('salida: !tracking'); return; }"],
  ['if(e.cancelable === false) return;', "if(e.cancelable === false){ TRACE.push('salida: cancelable false'); return; }"],
  ['if(Date.now() < suppressUntil) return;', "if(Date.now() < suppressUntil){ TRACE.push('salida: suppressUntil'); return; }"],
  ['if(!t) return;', "if(!t){ TRACE.push('salida: sin changedTouches'); return; }"],
  ['if(!isTappable(target)) return;', "if(!isTappable(target)){ TRACE.push('salida: no tappable'); return; }"]
];
marks.forEach(function (m) {
  if (fnSrc.indexOf(m[0]) < 0) { console.log('AVISO: no encontrado -> ' + m[0]); }
  fnSrc = fnSrc.replace(m[0], m[1]);
});
// traza de entrada en isTouchUI y en handleTap
fnSrc = fnSrc.replace('function isTouchUI(){', "function isTouchUI(){ TRACE.push('isTouchUI consultado');");
fnSrc = fnSrc.replace('function handleTap(target, x, y){', "function handleTap(target, x, y){ TRACE.push('handleTap ENTRADA');");

const dL = [];
const doc = { addEventListener(t, f, o) { dL.push({ t: t, f: f, c: !!(o && o.capture) }); } };
function fire(t, ev, cap) { dL.filter(function (l) { return l.t === t && (!cap || l.c); }).forEach(function (l) { l.f(ev); }); }
const btn = {
  _name: 'button', _attrs: { onclick: 'x' }, _delivered: 0,
  dispatchEvent: function () { this._delivered++; },
  addEventListener: function () {},
  getAttribute: function (k) { return this._attrs[k] || null; },
  closest: function () { return this; }
};
const TRACE = [];
const f = new Function('document', 'isTouch', 'navigator', 'window', 'MouseEvent', 'loadUrl', 'TRACE',
  fnSrc + '; return initGlobalTapToClick;');
const init = f(doc, true, { maxTouchPoints: 5 }, { innerWidth: 400 },
  function (t, i) { return Object.assign({ type: t }, i || {}); }, null, TRACE);

fire('touchstart', { touches: [{ clientX: 50, clientY: 50 }], cancelable: true, defaultPrevented: false }, true);
console.log('tras touchstart -> TRACE:', JSON.stringify(TRACE));
TRACE.length = 0;
fire('touchend', { target: btn, cancelable: true, defaultPrevented: false, changedTouches: [{ clientX: 50, clientY: 50 }] }, true);
console.log('tras touchend   -> TRACE:', JSON.stringify(TRACE));
console.log('delivered:', btn._delivered);
