{"content": "/**
 * Reproduce el flujo REAL de un tap sobre un icono del escritorio, tal como
 * funcionó cuando "sí abría": el manejador es ondblclick (atributo en el HTML).
 * Verifica que el tap abre la app UNA vez, con los dos comportamientos de
 * navegador (con y sin click nativo).
 * Uso: node tools/dev/tap-icon-flow-test.js
 */
const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, '..', '..', 'js', 'console.js'), 'utf8');
const start = src.indexOf('function initGlobalTapToClick()');
let depth = 0, end = -1, started = false;
for (let i = start; i < src.length; i++) {
  const c = src[i];
  if (c === '{') { depth++; started = true; }
  else if (c === '}') { depth--; if (started && depth === 0) { end = i + 1; break; } }
}
const fnSrc = src.slice(start, end);

let pass = 0, fail = 0;
function check(label, cond, extra) {
  if (cond) { pass++; console.log('  PASS  ' + label); }
  else { fail++; console.log('  FAIL  ' + label + (extra !== undefined ? '  -> ' + JSON.stringify(extra) : '')); }
}

/** Crea un entorno con N iconos .dicon con atributo ondblclick (como el HTML real) */
function makeEnv() {
  const docListeners = [];
  const doc = { addEventListener(t, f, o) { docListeners.push({ t: t, f: f, c: !!(o && o.capture), phase: 'doc' }); } };
  const log = [];
  const els = [];
  function mk(attrs, classes, name) {
    const el = {
      _name: name || 'div', _attrs: attrs, _classes: classes || [], _parent: doc, _clicks: 0, _dblclicks: 0,
      _listeners: [],
      addEventListener(t, f) { this._listeners.push({ t: t, f: f }); },
      removeEventListener() {},
      getAttribute(k) { return (k in this._attrs) ? this._attrs[k] : null; },
      dispatchEvent(ev) {
        // Entrega real: el propio elemento y luego burbujeo por el árbol
        let n = this;
        while (n) {
          if (n._listeners) n._listeners.forEach(function (l) { if (l.t === ev.type) l.f(ev); });
          if (ev.type === 'click' && n._attrs && n._attrs.onclick) n._exec('onclick');
          if (ev.type === 'dblclick' && n._attrs && n._attrs.ondblclick) n._exec('ondblclick');
          if (ev.type === 'click') n._clicks = (n._clicks || 0) + 1;
          n = n._parent || null;
        }
        ev._delivered = true;
        return true;
      },
      _exec(kind) { log.push(this._attrs._id + ':' + kind); },
      closest(sel) {
        let n = this;
        while (n && n !== doc) {
          const parts = String(sel).split(',').map(function (s) { return s.trim(); });
          for (const p of parts) {
            if (p === 'button' || p === 'a') { if (n._name === p) return n; }
            else if (p[0] === '.') { if (n._classes && n._classes.indexOf(p.slice(1)) >= 0) return n; }
            else if (p[0] === '[') {
              const a = p.slice(1, -1).split('=')[0];
              if (n._attrs && (a in n._attrs)) return n;
            }
          }
          n = n._parent || null;
        }
        return null;
      },
      getBoundingClientRect() { return { left: 0, top: 0, width: 80, height: 80 }; }
    };
    els.push(el);
    return el;
  }
  const f = new Function('document', 'isTouch', 'navigator', 'window', 'MouseEvent', 'loadUrl',
    fnSrc + '\n; return initGlobalTapToClick;');
  const win = { innerWidth: 400 };
  const init = f(doc, true, { maxTouchPoints: 5 }, win,
    function (type, o) { return Object.assign({ type: type, defaultPrevented: false, cancelable: true }, o || {}); },
    function () { log.push('loadUrl'); });
  init();
  function fireDoc(type, ev, cap) {
    docListeners.filter(function (l) { return l.t === type && (!cap || l.c); })
      .forEach(function (l) { l.f(ev); });
  }
  function tap(el, opts) {
    opts = opts || {};
    fireDoc('touchstart', { touches: [{ clientX: 40, clientY: 40 }], cancelable: true, defaultPrevented: false }, true);
    fireDoc('touchend', {
      target: el, cancelable: true, defaultPrevented: false,
      changedTouches: [{ clientX: opts.x === undefined ? 40 : opts.x, clientY: opts.y === undefined ? 40 : opts.y }]
    }, true);
  }
  function nativeClick(el) {
    fireDoc('click', { type: 'click', target: el, defaultPrevented: false }, true);
    el.dispatchEvent({ type: 'click', target: el });
  }
  return { mk: mk, tap: tap, fireDoc: fireDoc, nativeClick: nativeClick, log: log, doc: doc };
}

// ===== Escenario A: iOS (sin click nativo) =====
console.log('=== A. Icono con ondblclick, navegador SIN click nativo (iOS) ===');
{
  const env = makeEnv();
  const icon = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon'], 'div');
  env.tap(icon);
  check('el tap ejecutó la acción del icono', env.log.length >= 1, env.log);
  check('se ejecutó exactamente una vez', env.log.length === 1, env.log);
}

// ===== Escenario B: Android (click nativo ANTES del tap) =====
console.log('\n=== B. Icono con ondblclick, navegador CON click nativo (Android) ===');
{
  const env = makeEnv();
  const icon = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon'], 'div');
  // Chrome Android entrega un click tras el toque; en el flujo real ese click
  // llega DESPUÉS del touchend de mi listener, pero probamos el caso peor:
  // un click nativo reciente antes del tap.
  env.nativeClick(icon);
  const trasClick = env.log.slice();
  env.tap(icon);
  check('el click nativo no ejecuta ondblclick (correcto)', trasClick.length === 0, trasClick);
  check('el tap ejecutó la acción', env.log.length >= 1, env.log);
  check('sin duplicar', env.log.length === 1, env.log);
}

// ===== Escenario C: dos iconos distintos, taps seguidos =====
console.log('\n=== C. Dos taps en apps distintas (uso normal) ===');
{
  const env = makeEnv();
  const a = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon']);
  const b = env.mk({ ondblclick: "openNaves()", _id: 'ships' }, ['dicon']);
  env.tap(a);
  env.tap(b);
  check('el primer tap abrió Memes', env.log.indexOf('memes:ondblclick') >= 0, env.log);
  check('el segundo tap abrió Ships', env.log.indexOf('ships:ondblclick') >= 0, env.log);
}

// ===== Escenario D: tap en botón de ventana (onclick en atributo) =====
console.log('\n=== D. Botón dentro de una ventana (onclick) ===');
{
  const env = makeEnv();
  const btn = env.mk({ onclick: "openWindow('win-games')", _id: 'games' }, [], 'button');
  env.tap(btn);
  check('el tap ejecutó el onclick', env.log.indexOf('games:onclick') >= 0, env.log);
  check('sin duplicar', env.log.filter(function (x) { return x === 'games:onclick'; }).length === 1, env.log);
}

// ===== Escenario E: el clic de un botón NO debe disparar el ondblclick del padre =====
console.log('\n=== E. Botón ✕ dentro de un icono/contenedor con ondblclick ===');
{
  const env = makeEnv();
  const cont = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'cont' }, ['dicon']);
  const closeBtn = env.mk({ onclick: "closeWindow('win-memes')", _id: 'cerrar' }, [], 'button');
  closeBtn._parent = cont;
  env.tap(closeBtn);
  check('se ejecutó el onclick del botón', env.log.indexOf('cerrar:onclick') >= 0, env.log);
  check('NO se ejecutó el ondblclick del contenedor', env.log.indexOf('cont:ondblclick') < 0, env.log);
}

console.log('\n=== RESULTADO: ' + pass + ' OK, ' + fail + ' fallos ===');
process.exit(fail ? 1 : 0);
", "file_path": "C:\Users\BFFF\Documents\proyecto\tools\dev\tap-icon-flow-test.js"}

