{
  const env = makeEnv();
  const icon = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon'], 'div');
  // Observamos las ejecuciones reales de new Function (vía de respaldo) y de
  // los handlers de atributo.
  const origFunction = global.Function;
  const ejecutados = [];
  global.Function = function (a, b) {
    if ((a === 'event' || a === undefined) && typeof b === 'string') ejecutados.push(b);
    return origFunction.apply(null, arguments);
  };
  try { env.tap(icon); } finally { global.Function = origFunction; }
  check('el tap disparó la acción del icono (ondblclick)', ejecutados.length >= 1, { ejecutados: ejecutados, log: env.log });
  check('se ejecutó exactamente una vez', ejecutados.length === 1, ejecutados);
}
