{"file_path": "C:\Users\BFFF\Documents\proyecto\tools\dev\tap-icon-flow-test.js", "new_string": "/** Ejecuta una acción y cuenta las veces que se ejecuta el handler del elemento,
 *  observando tanto la ejecución por atributo (vía de respaldo) como el disparo
 *  de eventos (síntesis). Devuelve { taps: fn, ejecutados: [] }. */
function withProbe(fn) {
  const origFunction = global.Function;
  const ejecutados = [];
  global.Function = function (a, b) {
    if ((a === 'event' || a === undefined) && typeof b === 'string') ejecutados.push(b);
    return origFunction.apply(null, arguments);
  };
  try { fn(); } finally { global.Function = origFunction; }
  return ejecutados;
}

// ===== Escenario A: iOS (sin click nativo) =====
console.log('=== A. Icono con ondblclick, navegador SIN click nativo (iOS) ===');
{
  const env = makeEnv();
  const icon = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon'], 'div');
  const ejecutados = withProbe(function () { env.tap(icon); });
  check('el tap disparó la acción del icono (ondblclick)', ejecutados.length >= 1, { ejecutados: ejecutados });
  check('se ejecutó exactamente una vez', ejecutados.length === 1, ejecutados);
}

// ===== Escenario B: Android (click nativo ANTES del tap) =====
console.log('\n=== B. Icono con ondblclick, navegador CON click nativo (Android) ===');
{
  const env = makeEnv();
  const icon = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon'], 'div');
  // Chrome Android entrega un click tras el toque. Probamos el caso peor: un
  // click nativo inmediatamente antes del tap.
  withProbe(function () { env.nativeClick(icon); });
  const ejecutados = withProbe(function () { env.tap(icon); });
  check('el tap ejecutó la acción (no se bloquea por el click nativo)', ejecutados.length >= 1, { ejecutados: ejecutados });
  check('sin duplicar', ejecutados.length === 1, ejecutados);
}

// ===== Escenario C: dos iconos distintos, taps seguidos =====
console.log('\n=== C. Dos taps en apps distintas (uso normal) ===');
{
  const env = makeEnv();
  const a = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'memes' }, ['dicon']);
  const b = env.mk({ ondblclick: "openNaves()", _id: 'ships' }, ['dicon']);
  const ejecutados = withProbe(function () { env.tap(a); env.tap(b); });
  check('el primer tap abrió Memes', ejecutados.indexOf("openWindow('win-memes')") >= 0, ejecutados);
  check('el segundo tap abrió Ships', ejecutados.indexOf('openNaves()') >= 0, ejecutados);
}

// ===== Escenario D: tap en botón de ventana (onclick en atributo) =====
console.log('\n=== D. Botón dentro de una ventana (onclick) ===');
{
  const env = makeEnv();
  const btn = env.mk({ onclick: "openWindow('win-games')", _id: 'games' }, [], 'button');
  const ejecutados = withProbe(function () { env.tap(btn); });
  check('el tap ejecutó el onclick', ejecutados.indexOf("openWindow('win-games')") >= 0, ejecutados);
  check('sin duplicar', ejecutados.filter(function (x) { return x === "openWindow('win-games')"; }).length === 1, ejecutados);
}

// ===== Escenario E: el toque en ✕ no debe disparar el ondblclick del padre =====
console.log('\n=== E. Botón ✕ dentro de un contenedor con ondblclick ===');
{
  const env = makeEnv();
  const cont = env.mk({ ondblclick: "openWindow('win-memes')", _id: 'cont' }, ['dicon']);
  const closeBtn = env.mk({ onclick: "closeWindow('win-memes')", _id: 'cerrar' }, [], 'button');
  closeBtn._parent = cont;
  const ejecutados = withProbe(function () { env.tap(closeBtn); });
  check('se ejecutó el onclick del botón', ejecutados.indexOf("closeWindow('win-memes')") >= 0, ejecutados);
  check('NO se ejecutó el ondblclick del contenedor', ejecutados.indexOf("openWindow('win-memes')") < 0, ejecutados);
}

// ===== Escenario F: tap seguido (dos apps en menos de 350 ms) =====
