/** Ejecuta una acción y cuenta las veces que se ejecuta el handler del elemento,
 *  observando tanto la ejecución por atributo (vía de respaldo) como el disparo
 *  de eventos (síntesis). Devuelve { taps: fn, ejecutados: [] }. */
function withProbe(fn) {
  const origFunction = global.Function;
  const ejecutados = [];
  global.Function = function (a, b) {
    if ((a === 'event' || a === undefined) && typeof b === 'string') ejecutados.push(b);
    return origFunction.apply(null, arguments);
  };
  try { fn(); } finally { global.Function = origFunction; }
  return ejecutados;
}

