    const nativeAdd = proto.addEventListener;
    const nativeRemove = proto.removeEventListener;
    proto.addEventListener = function(type, fn, opts){
      if((type === 'click' || type === 'dblclick') && typeof fn === 'function' && this && typeof this === 'object'){
