{"content": "/**
 * Recupera js/console.js a partir del transcript de la sesión: las lecturas
 * quedaron registradas con sus números de línea, así que se reconstruye el
 * archivo uniendo todos los rangos disponibles.
 *
 * Uso: node tools/dev/_recover-console.js <ruta-del-transcript.jsonl>
 */
const fs = require('fs');
const path = require('path');

const transcriptPath = process.argv[2];
if (!transcriptPath || !fs.existsSync(transcriptPath)) {
  console.log('FATAL: falta la ruta del transcript');
  process.exit(1);
}

const raw = fs.readFileSync(transcriptPath, 'utf8');
console.log('transcript: ' + (raw.length / 1024 / 1024).toFixed(2) + ' MB');

// Las lecturas aparecen como bloques numerados tipo "  1234→contenido".
// Se acepta cualquier longitud de padding y el separador → o ->.
const lineRe = /^\s*(\d+)(?:→|->)(.*)$/;
const found = new Map();   // numero de linea -> contenido

let scanned = 0;
raw.split(/\r?\n/).forEach(function (ln) {
  // El JSON escapa los saltos, así que también se buscan \n escapados
  const pieces = ln.split(/\\n/);
  pieces.forEach(function (piece) {
    const m = piece.match(lineRe);
    if (!m) return;
    const n = parseInt(m[1], 10);
    if (!n || n > 20000) return;
    let content = m[2];
    // Desescapar lo que JSON haya dejado
    content = content.replace(/\\"/g, '"').replace(/\\\\/g, '\\').replace(/\\t/g, '\t');
    if (!found.has(n)) { found.set(n, content); scanned++; }
  });
});

console.log('lineas recuperadas: ' + found.size);

const nums = Array.from(found.keys()).sort(function (a, b) { return a - b; });
if (nums.length) {
  console.log('rango: ' + nums[0] + ' .. ' + nums[nums.length - 1]);
  // Huecos (solo informativo: no todo el archivo se leyó)
  const holes = [];
  let prev = nums[0];
  nums.forEach(function (n) {
    if (n > prev + 1) holes.push(prev + 1 + '-' + (n - 1));
    prev = n;
  });
  console.log('huecos (' + holes.length + '): ' + holes.slice(0, 40).join(', ') + (holes.length > 40 ? ' …' : ''));
}

// Guardar el material recuperado para inspección
const out = nums.map(function (n) { return n + '|' + found.get(n); }).join('\n');
fs.writeFileSync(path.join(__dirname, '_recovered_lines.txt'), out, 'utf8');
console.log('volcado a tools/dev/_recovered_lines.txt');
", "file_path": "C:\Users\BFFF\Documents\proyecto\tools\dev\_recover-console.js"}

